from random import randint, seed
import pandas as pd

# Method
def task_func(goals, penalties, rng_seed=None):
    if rng_seed is not None:
        seed(rng_seed)

    def _as_list(value):
        if isinstance(value, (str, bytes)):
            raise TypeError("goals and penalties must be numeric values or sequences of numeric values")
        try:
            return list(value), True
        except TypeError:
            return [value], False

    goals_list, goals_is_iter = _as_list(goals)
    penalties_list, penalties_is_iter = _as_list(penalties)

    if goals_is_iter and penalties_is_iter:
        if len(goals_list) != len(penalties_list):
            raise ValueError("goals and penalties must have the same length")
    elif goals_is_iter and not penalties_is_iter:
        penalties_list = penalties_list * len(goals_list)
    elif penalties_is_iter and not goals_is_iter:
        goals_list = goals_list * len(penalties_list)

    if len(goals_list) == 0 and len(penalties_list) == 0:
        return pd.DataFrame(columns=["Team", "Match Result"])

    for value in goals_list:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("goals must contain integers")
        if value < 0:
            raise ValueError("goals must be non-negative")
    for value in penalties_list:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("penalties must contain integers")
        if value < 0:
            raise ValueError("penalties must be non-negative")

    FINE_COST = 100
    teams = [f"Team {i + 1}" for i in range(len(goals_list))]
    match_results = [f"Goals: {g}, Fine: {p * FINE_COST}" for g, p in zip(goals_list, penalties_list)]

    return pd.DataFrame({"Team": teams, "Match Result": match_results})
